def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    cars = image_patch.find("white car")
    plaza_patches = image_patch.find("plaza")

    if not cars or not plaza_patches:
        return image_patch

    plaza_center_x = sum(p.horizontal_center for p in plaza_patches) / len(plaza_patches)

    left_cars = [car for car in cars if car.horizontal_center < plaza_center_x]
    right_cars = [car for car in cars if car.horizontal_center >= plaza_center_x]

    if not left_cars and not right_cars:
        return image_patch

    if not left_cars:
        return min(right_cars, key=lambda p: p.horizontal_center)

    if not right_cars:
        return max(left_cars, key=lambda p: p.horizontal_center)

    left_distance = abs(min(left_cars, key=lambda p: p.horizontal_center).horizontal_center - plaza_center_x)
    right_distance = abs(max(right_cars, key=lambda p: p.horizontal_center).horizontal_center - plaza_center_x)

    return left_cars[0] if left_distance <= right_distance else right_cars[0]

